// Android "Quick add" home-screen widget. A widget is native (an AppWidgetProvider rendering RemoteViews),
// and android/ is regenerated by prebuild, so the provider and its resources live here and are copied in.
// Plain RemoteViews and a static layout need no library: no widget dependency, no headless JS.
const fs = require("fs");
const path = require("path");
const { withAndroidManifest, withDangerousMod, AndroidConfig } = require("expo/config-plugins");

const PROVIDER = "QuickAddWidgetProvider";
const SCHEME = "recur";

/** @type {import("expo/config-plugins").ConfigPlugin} */
module.exports = function withQuickAddWidget(config) {
  const pkg = config.android?.package;
  if (!pkg) {
    throw new Error("withQuickAddWidget: android.package must be set in app.json.");
  }
  const schemes = [config.scheme ?? []].flat();
  // QuickAddWidgetProvider.kt hardcodes recur://quick-add/ URLs.
  if (!schemes.includes(SCHEME)) {
    throw new Error(`withQuickAddWidget: app.json scheme must include "${SCHEME}".`);
  }
  const receiverName = `${pkg}.${PROVIDER}`;

  config = withAndroidManifest(config, (cfg) => {
    const app = AndroidConfig.Manifest.getMainApplicationOrThrow(cfg.modResults);
    app.receiver = (app.receiver ?? []).filter((r) => r.$["android:name"] !== receiverName);
    app.receiver.push({
      $: {
        "android:name": receiverName,
        "android:exported": "false",
        "android:label": "@string/quick_add_widget_label",
      },
      "intent-filter": [{ action: [{ $: { "android:name": "android.appwidget.action.APPWIDGET_UPDATE" } }] }],
      "meta-data": [
        { $: { "android:name": "android.appwidget.provider", "android:resource": "@xml/quick_add_widget_info" } },
      ],
    });
    return cfg;
  });

  return withDangerousMod(config, [
    "android",
    async (cfg) => {
      const mainDir = path.join(cfg.modRequest.platformProjectRoot, "app", "src", "main");
      await fs.promises.cp(path.join(__dirname, "android", "res"), path.join(mainDir, "res"), {
        recursive: true,
        force: true,
      });
      const source = await fs.promises.readFile(path.join(__dirname, "android", `${PROVIDER}.kt`), "utf8");
      const javaDir = path.join(mainDir, "java", ...pkg.split("."));
      await fs.promises.mkdir(javaDir, { recursive: true });
      await fs.promises.writeFile(path.join(javaDir, `${PROVIDER}.kt`), `package ${pkg}\n\n${source}`);
      return cfg;
    },
  ]);
};
